	if len(args) != 1 {
		return shim.Error("invalid add person chaincode invocation")
	}

	person := &Person{}
	if err := json.Unmarshal([]byte(args[0]), person); err != nil {
		return shim.Error("Invalid JSON input")
	}

	if person.FirstName == "" || person.LastName == "" || person.PassportID == "" || person.Address == "" || person.Phone == "" {
		return shim.Error("Missing required fields")
	}

	key := fmt.Sprintf("%s_%s", person.PassportID, time.Now().Format("20060102150405"))
	pp, err := stub.GetState(key)
	if err != nil {
		return shim.Error(err.Error())
	}

	if pp != nil {
		return shim.Error(fmt.Sprintf("Person with id %s already exists", person.PassportID))
	}

	if err := stub.PutState(key, []byte(args[0])); err != nil {
		return shim.Error(err.Error())
	}

	return shim.Success(nil)
}
```

